CREATE TABLE v51269 (v51270 INT, v51271 INT, v51272 INT, v51273 INT, v51274 INT) AS SELECT MBROVERLAPS(@horiz1, @horiz3), ST_ASTEXT(ST_GEOMFROMTEXT('MULTIPOINT(1 0,15 0,10 10)')), SPACE(18446744073709551616), X(1, 1, 1, 1, 1, 1, 'x'), MBRTOUCHES(ST_GEOMFROMTEXT('MULTIPOINT(5 0,5 10)'), ST_GEOMFROMTEXT('MULTIPOINT(5 10,5 15)')), TIMEDIFF(CAST('00:00:00.0' AS TIME), CAST('00:00:00' AS TIME)), REGEXP_INSTR(x6, '[a-z]+', 385025119, 1, x7)